This Terraform configuration creates an AWS Route 53 public hosted zone and an `A` record that maps a domain name to a specific IPv4 address. Default values are provided for the domain name, subdomain, and IPv4 address, so the configuration is deployable as-is after AWS credentials are configured.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region used for the provider configuration. Route 53 is global, but the AWS provider still requires a region."
  type        = string
  default     = "us-east-1"
}

variable "domain_name" {
  description = "The root domain name for the Route 53 hosted zone."
  type        = string
  default     = "example.com"
}

